/* Evidence views use saved real run records, never interpolated training data. */
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function imageCard(url,label){const f=el('figure'),img=el('img');img.src=url;img.alt=label;img.loading='lazy';f.append(img,el('figcaption',label));return f;}
function renderAuthorInputs(){for(const root of document.querySelectorAll('.author-inputs')){root.replaceChildren();for(const r of S.authors?.records||[]){const b=el('button');b.disabled=S.busy;const img=el('img');img.src=r.url;img.alt=L(r.title);b.append(img,el('span',L(r.title)));b.classList.toggle('selected',S.inputInfo?.authorId===r.id);b.onclick=()=>loadAuthor(r);root.append(b);}}}
async function loadAuthor(r){if(S.busy)return;const blob=await(await fetch(r.url)).blob();await upload(new File([blob],r.originalFilename,{type:'image/jpeg'}));S.inputInfo={...S.inputInfo,authorId:r.id,photographer:L(r.photographer),photographerBilingual:r.photographer,rights:L(r.rights),rightsBilingual:r.rights,role:r.role,sourceFileSHA256:r.originalSHA256,displayDerivativeSHA256:r.sha256,sourceOriginalDimensions:r.originalDimensions,selfShotStatus:'provided by project author; authorized in conversation 2026-10-12'};renderInput();selectors();renderAuthorInputs();}
function renderTrainingEvidence(){const root=$('trainingEvidence');root.replaceChildren();root.className='training-results';const run=S.run;if(!run){root.append(el('p',T('curvePendingText')));return;}const summary=el('div',undefined,'metrics');for(const [label,value]of [[T('epochs'),run.epochs],[T('validationAccuracy'),(run.logs[run.selectedCheckpoint?.epoch||run.epochs].valAccuracy*100).toFixed(1)+'%'],[T('testAccuracy'),run.test?run.test.predictions.filter(r=>r.truth===r.predicted).length+'/'+run.test.predictions.length+' · '+(run.test.accuracy*100).toFixed(1)+'%':'—'],[T('checkpoints'),run.checkpoints.length]]){const card=el('article');card.append(el('strong',String(value)),el('span',label));summary.append(card);}root.append(summary,el('p',T('trainingMethod'),'technical-note'));
const chart=el('div',undefined,'chart-box'),svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 700 250');svg.setAttribute('role','img');svg.setAttribute('aria-label',T('lossChart'));const max=Math.max(...run.logs.flatMap(x=>[x.trainLoss,x.valLoss]))*1.1;const ns=svg.namespaceURI;function line(points,color){const p=document.createElementNS(ns,'polyline');p.setAttribute('points',points);p.setAttribute('fill','none');p.setAttribute('stroke',color);p.setAttribute('stroke-width','3');svg.append(p);}for(let i=0;i<5;i++){const y=210-i*45;line(`50,${y} 670,${y}`,'#394330');const t=document.createElementNS(ns,'text');t.setAttribute('x','3');t.setAttribute('y',y+5);t.setAttribute('fill','#b9c1aa');t.textContent=(max*i/4).toFixed(2);svg.append(t);}for(const [key,color]of [['trainLoss','#d4b77b'],['valLoss','#a5c4cc']])line(run.logs.map(r=>`${50+r.epoch/run.epochs*620},${210-r[key]/max*180}`).join(' '),color);chart.append(el('h4',T('lossChart')),svg,el('p',T('curveLegend')));root.append(chart);
const table=el('table'),head=el('tr');for(const h of [T('epoch'),T('trainLoss'),T('valLoss'),T('trainAccuracy'),T('validationAccuracy')])head.append(el('th',h));table.append(head);for(const r of run.logs){const row=el('tr');for(const v of [r.epoch,r.trainLoss.toFixed(4),r.valLoss.toFixed(4),(100*r.trainAccuracy).toFixed(1)+'%',(100*r.valAccuracy).toFixed(1)+'%'])row.append(el('td',String(v)));table.append(row);}const details=el('details',undefined,'audit');details.append(el('summary',T('actualValues')),table);root.append(details);
if(run.test){const p=el('p',T('selectionRule'),'notice');root.append(p);const conf=el('table'),row=el('tr');row.append(el('th',T('truthPrediction')));for(const k of ['classCockroach','classOther','classSpace'])row.append(el('th',T(k)));conf.append(row);run.test.confusion.forEach((a,i)=>{const r=el('tr');r.append(el('th',T(['classCockroach','classOther','classSpace'][i])));a.forEach(n=>r.append(el('td',String(n))));conf.append(r);});root.append(conf);}
const cp=$('checkpointComparison');cp.replaceChildren(el('h3',T('checkpointCompare')),el('p',T('checkpointRule')));const cards=el('div',undefined,'checkpoint-grid');for(const c of run.checkpoints){const card=el('article'),saved=S.evidence?.checkpoints?.find(v=>v.epoch===c.epoch);card.append(el('h4',`${T('epoch')} ${c.epoch}`));if(saved)card.append(imageCard(saved.final,T('computedDream')),el('p',`${T('logit')}: ${saved.before.logit.toFixed(3)} → ${saved.after.logit.toFixed(3)}`));const a=el('a',c.id);a.href=c.url;card.append(a,el('code',c.sha256));cards.append(card);}cp.append(cards);}
function renderRealFailures(){const root=$('failureGallery');root.replaceChildren();if(!S.evidence?.gallery?.length){root.append(el('p',T('awaitingTest')));return;}for(const r of S.evidence.gallery){const a=el('article');a.append(el('h4',L(r.title)),el('p',L(r.observation),'failure-observation'));const imgs=el('div',undefined,'failure-images');imgs.append(imageCard(r.input,T('original')),imageCard(r.baseline.final,T('baseDream')),imageCard(r.fineTuned.final,T('fineDream')));a.append(imgs);if(r.channelError)a.append(el('p',`${r.channelError.layer} / ch ${r.channelError.channel}: ${r.channelError.baselineValue.toFixed(4)} → ${r.channelError.value.toFixed(4)} · ${T('threshold')} ${r.channelError.threshold.toFixed(4)}`));for(const id of ['baseline','fineTuned']){const v=r[id];a.append(el('p',`${T(id==='baseline'?'baseModel':'fineModel')}: ${T('logit')} ${v.before.logit.toFixed(3)} · p ${v.before.score.toFixed(6)} → ${v.after.score.toFixed(6)}`));}a.append(el('p',T('classificationDecision')+': '+L(r.decision)),el('p',L(r.sourceLabel),'technical-note'));if(r.sourceURL){const source=el('a',T('photoSource'));source.href=r.sourceURL;source.target='_blank';source.rel='noreferrer';a.append(source);}const link=el('a',T('evidenceRecord'));link.href=r.recordURL;a.append(link);root.append(a);}}
function renderPresetEvidence(){const root=$('presetEvidence');root.replaceChildren();const p=S.evidence?.preset;if(!p)return;root.append(el('p',L(p.rule)),el('p',`${p.layer} / ch ${p.channel} · ${T('threshold')}: ${p.threshold.toFixed(4)}`),el('p',L(p.conclusion)));const b=el('button',T('usePreset'));b.disabled=S.locked;b.onclick=()=>{change('target',p.layer);change('channel',p.channel);};root.append(b);for(const r of p.examples){root.append(imageCard('experiment/evaluation-inputs/'+r.id+'.png',r.id));root.append(el('p',`${r.id} · ${T('truth')}: ${T({cockroach:'classCockroach',other_insect:'classOther',empty_space:'classSpace'}[r.truth])} · ${r.value.toFixed(4)} · ${T(r.correct?'presetSuccess':'presetFailure')}`));}}

async function replayEvidence(){const e=S.evidence?.gallery.find(r=>r.id===S.inputInfo?.authorId);if(!e||S.busy)return;const r=await json(e.recordURL);selectRecord(r);stage('case');caseTab('dream');}
